def build():
    records = {}
    used = set()
    for key, data in GROUPS.items():
        for n in data['names']:
            if n not in CARDS:
                if n in RETIRED:
                    continue
                raise ValueError(('Unknown binding', key, n))
            used.add(n)
    missing = set(CARDS) - used
    if missing:
        raise ValueError(('Unclassified cards', sorted(missing)))
    for n, c in CARDS.items():
        roles = [dict(role=k, planning=d['plan'], formal=d['formal']) for k, d in GROUPS.items() if n in d['names']]
        records[n] = dict(element=c.element, rarity=c.rarity, card_text=c.text, roles=roles, specific_rule=SPECIAL.get(n, '按本卡原文数值执行上述角色绑定；固定面板、首次层和能力仅正式到位生效，死亡截断尾段无效果。'), commit_scope='reached_prefix_only', runtime_migrated=True)
    return records

def main():
    records = build()
    folder = ROOT / 'docs/cards-v1.2'
    result = dict(version='1.2', status='locked_runtime_with_regression', cards=len(records), death_rule='lethal_position_truncates_queue_even_if_revived; lifeguard_at_1_does_not_truncate', role_counts=dict(Counter((role['role'] for row in records.values() for role in row['roles']))), specific_rules=len(SPECIAL), records=records)
    (folder / 'snapshot-contract.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    lines = ['# v1.2逐卡跨层读取表', '', '由tools/audit_v12_layers.py生成。185张全部有显式角色绑定并接入strict运行；逐卡执行与交互回归见tools/sim_v12/test_current.py，执行覆盖不等于穷举组合。', '统一术语、死亡截断、治疗资源与实际事件去重见[snapshot-contract.md](snapshot-contract.md)。特例优先于角色通则；原卡面数值不变。', '', '|卡牌|元素/品质|角色|读取与提交的具体处理|', '|---|---|---|---|']
    for n, row in records.items():
        note = row['specific_rule']
        if n not in SPECIAL:
            note = '；'.join(dict.fromkeys((r['planning'] + ' ' + r['formal'] for r in row['roles'])))
        lines.append('|' + n + '|' + row['element'] + '/' + row['rarity'] + '|' + '、'.join((r['role'] for r in row['roles'])) + '|' + note + '|')
    (folder / 'snapshot-audit.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    out = ROOT / 'research/v1.2-snapshot-contract-20261028'
    out.mkdir(exist_ok=True)
    (out / 'audit-summary.json').write_text(json.dumps(dict(cards=len(records), unclassified=[], specific_rules=len(SPECIAL), role_counts=result['role_counts'], runtime_migrated=True, quick_test_started=False, sha256={p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in (folder / 'snapshot-contract.md', folder / 'snapshot-contract.json', folder / 'snapshot-audit.md')}), ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(dict(cards=len(records), specific_rules=len(SPECIAL), unclassified=[]), ensure_ascii=True))
if __name__ == '__main__':
    main()
